  /// arrays cannot be read from or derived from feature properties. In line widths. At least 0.
  public var lineDasharray: TileflowValue<[Double]>?
  /// How `lineDasharray` changes when it is set.
  public var lineDasharrayTransition: TileflowTransition?
  /// Name of image in sprite to use for drawing image lines. For seamless patterns, image width
  /// must be a factor of two (2, 4, 8, ..., 512). Note that zoom-dependent expressions will be
  /// evaluated only at integer zoom levels.
  public var linePattern: TileflowValue<String>?
  /// How `linePattern` changes when it is set.
  public var linePatternTransition: TileflowTransition?
  /// Defines a gradient with which to color a line feature. Can only be used with GeoJSON sources
  /// that specify `"lineMetrics": true`.
  public var lineGradient: TileflowValue<TileflowColor>?

  public init(id: String, source: String) {
    self.id = id
    self.source = source
  }

  public func encode(to encoder: any Encoder) throws {
    var style = StyleLayerEncoding(id: id, type: Self.type)
    style.source = source
    style.sourceLayer = sourceLayer
    style.filter = filter
    style.minZoom = minZoom
    style.maxZoom = maxZoom
    style.layout("line-cap", lineCap)
    style.layout("line-join", lineJoin)
    style.layout("line-miter-limit", lineMiterLimit)
    style.layout("line-round-limit", lineRoundLimit)
    style.layout("line-sort-key", lineSortKey)
    style.layout("visibility", visibility)
    style.paint("line-opacity", lineOpacity)
    style.paint("line-opacity-transition", lineOpacityTransition)
    style.paint("line-layer-opacity", lineLayerOpacity)
    style.paint("line-layer-opacity-transition", lineLayerOpacityTransition)
    style.paint("line-color", lineColor)
    style.paint("line-color-transition", lineColorTransition)
    style.paint("line-translate", lineTranslate)
    style.paint("line-translate-transition", lineTranslateTransition)
    style.paint("line-translate-anchor", lineTranslateAnchor)
    style.paint("line-width", lineWidth)
    style.paint("line-width-transition", lineWidthTransition)
    style.paint("line-gap-width", lineGapWidth)
    style.paint("line-gap-width-transition", lineGapWidthTransition)
    style.paint("line-offset", lineOffset)
    style.paint("line-offset-transition", lineOffsetTransition)
    style.paint("line-blur", lineBlur)
    style.paint("line-blur-transition", lineBlurTransition)
    style.paint("line-dasharray", lineDasharray)
    style.paint("line-dasharray-transition", lineDasharrayTransition)
    style.paint("line-pattern", linePattern)
    style.paint("line-pattern-transition", linePatternTransition)
    style.paint("line-gradient", lineGradient)
    try style.encode(to: encoder)
  }
}

/// An icon or a text label. MapLibre layer type `symbol`.
public struct TileflowSymbolLayer: TileflowLayer, Equatable {
  public static let type = "symbol"
