  public var filter: TileflowExpression?
  /// The zoom level from which the layer shows.
  public var minZoom: Double?
  /// The zoom level from which the layer hides.
  public var maxZoom: Double?
  /// Where the layer lies among the map’s own layers; nil lies above them all.
  public var slot: TileflowLayerSlot?
  /// Whether this layer is displayed. Default: `"visible"`.
  public var visibility: TileflowValue<TileflowVisibility>?
  /// Radius of influence of one heatmap point in pixels. Increasing the value makes the heatmap
  /// smoother, but less detailed. In pixels. At least 1. Default: `30`.
  public var heatmapRadius: TileflowValue<Double>?
  /// How `heatmapRadius` changes when it is set.
  public var heatmapRadiusTransition: TileflowTransition?
  /// A measure of how much an individual point contributes to the heatmap. A value of 10 would be
  /// equivalent to having 10 points of weight 1 in the same spot. Especially useful when combined
  /// with clustering. At least 0. Default: `1`.
  public var heatmapWeight: TileflowValue<Double>?
  /// Similar to `heatmap-weight` but controls the intensity of the heatmap globally. Primarily used
  /// for adjusting the heatmap based on zoom level. At least 0. Default: `1`.
  public var heatmapIntensity: TileflowValue<Double>?
  /// How `heatmapIntensity` changes when it is set.
  public var heatmapIntensityTransition: TileflowTransition?
  /// Defines the color of each pixel based on its density value in a heatmap. Should be an
  /// expression that uses `["heatmap-density"]` as input. Default:
  /// `["interpolate",["linear"],["heatmap-density"],0,"rgba(0, 0, 255,
  /// 0)",0.1,"royalblue",0.3,"cyan",0.5,"lime",0.7,"yellow",1,"red"]`.
  public var heatmapColor: TileflowValue<TileflowColor>?
  /// The global opacity at which the heatmap layer will be drawn. From 0 to 1. Default: `1`.
  public var heatmapOpacity: TileflowValue<Double>?
  /// How `heatmapOpacity` changes when it is set.
  public var heatmapOpacityTransition: TileflowTransition?

  public init(id: String, source: String) {
    self.id = id
    self.source = source
  }

  public func encode(to encoder: any Encoder) throws {
    var style = StyleLayerEncoding(id: id, type: Self.type)
    style.source = source
    style.sourceLayer = sourceLayer
    style.filter = filter
    style.minZoom = minZoom
    style.maxZoom = maxZoom
    style.layout("visibility", visibility)
    style.paint("heatmap-radius", heatmapRadius)
    style.paint("heatmap-radius-transition", heatmapRadiusTransition)
    style.paint("heatmap-weight", heatmapWeight)
    style.paint("heatmap-intensity", heatmapIntensity)
    style.paint("heatmap-intensity-transition", heatmapIntensityTransition)
    style.paint("heatmap-color", heatmapColor)
    style.paint("heatmap-opacity", heatmapOpacity)
    style.paint("heatmap-opacity-transition", heatmapOpacityTransition)
    try style.encode(to: encoder)
  }
}

/// An extruded (3D) polygon. MapLibre layer type `fill-extrusion`.
public struct TileflowFillExtrusionLayer: TileflowLayer, Equatable {
  public static let type = "fill-extrusion"
  public var id: String
  /// The application source the layer draws.
  public var source: String
  /// The layer of a vector source to draw.
  public var sourceLayer: String?
  /// Draws only the features this expression accepts.
  public var filter: TileflowExpression?
  /// The zoom level from which the layer shows.
  public var minZoom: Double?
  /// The zoom level from which the layer hides.
  public var maxZoom: Double?
  /// Where the layer lies among the map’s own layers; nil lies above them all.
  public var slot: TileflowLayerSlot?
  /// Whether this layer is displayed. Default: `"visible"`.
  public var visibility: TileflowValue<TileflowVisibility>?
  /// The distance from each fill extrusion corner, measured along the adjacent edges, that is
  /// replaced by a rounded corner. A value of `0` disables rounded corners. In meters. At least 0.
  /// Default: `0`. Takes a constant only.
  public var fillExtrusionRoundedCornerDistance: Double?
  /// The opacity of the entire fill extrusion layer. This is rendered on a per-layer, not
  /// per-feature, basis, and data-driven styling is not available. From 0 to 1. Default: `1`.
  public var fillExtrusionOpacity: TileflowValue<Double>?
  /// How `fillExtrusionOpacity` changes when it is set.
  public var fillExtrusionOpacityTransition: TileflowTransition?
  /// The base color of the extruded fill. The extrusion's surfaces will be shaded differently based
  /// on this color in combination with the root `light` settings. If this color is specified as
  /// `rgba` with an alpha component, the alpha component will be ignored; use
  /// `fill-extrusion-opacity` to set layer opacity. Default: `"#000000"`.
  public var fillExtrusionColor: TileflowValue<TileflowColor>?
  /// How `fillExtrusionColor` changes when it is set.
  public var fillExtrusionColorTransition: TileflowTransition?
  /// The geometry's offset. Values are `[x, y]` where negatives indicate left and up (on the flat
  /// plane), respectively. In pixels. Default: `[0,0]`.
  public var fillExtrusionTranslate: TileflowValue<[Double]>?
  /// How `fillExtrusionTranslate` changes when it is set.
  public var fillExtrusionTranslateTransition: TileflowTransition?
  /// Controls the frame of reference for `fill-extrusion-translate`. Default: `"map"`.
  public var fillExtrusionTranslateAnchor: TileflowValue<TileflowFillExtrusionTranslateAnchor>?
  /// Name of image in sprite to use for drawing images on extruded fills. For seamless patterns,
  /// image width and height must be a factor of two (2, 4, 8, ..., 512). Note that zoom-dependent
  /// expressions will be evaluated only at integer zoom levels.
  public var fillExtrusionPattern: TileflowValue<String>?
  /// How `fillExtrusionPattern` changes when it is set.
  public var fillExtrusionPatternTransition: TileflowTransition?
  /// The height with which to extrude this layer. Negative values extrude below ground level, so a
  /// floor that is entirely underground can be expressed. In meters. Default: `0`.
  public var fillExtrusionHeight: TileflowValue<Double>?
  /// How `fillExtrusionHeight` changes when it is set.
  public var fillExtrusionHeightTransition: TileflowTransition?
  /// The height with which to extrude the base of this layer. Must be less than or equal to
  /// `fill-extrusion-height`. Negative values extrude below ground level, e.g. underground floors.
  /// In meters. Default: `0`.
  public var fillExtrusionBase: TileflowValue<Double>?
  /// How `fillExtrusionBase` changes when it is set.
  public var fillExtrusionBaseTransition: TileflowTransition?
  /// Whether to apply a vertical gradient to the sides of a fill-extrusion layer. If true, sides
  /// will be shaded slightly darker farther down. Default: `true`.
  public var fillExtrusionVerticalGradient: TileflowValue<Bool>?

  public init(id: String, source: String) {
    self.id = id
    self.source = source
  }

  public func encode(to encoder: any Encoder) throws {
    var style = StyleLayerEncoding(id: id, type: Self.type)
    style.source = source
    style.sourceLayer = sourceLayer
    style.filter = filter
    style.minZoom = minZoom
    style.maxZoom = maxZoom
    style.layout("visibility", visibility)
    style.layout("fill-extrusion-rounded-corner-distance", fillExtrusionRoundedCornerDistance)
    style.paint("fill-extrusion-opacity", fillExtrusionOpacity)
    style.paint("fill-extrusion-opacity-transition", fillExtrusionOpacityTransition)
    style.paint("fill-extrusion-color", fillExtrusionColor)
    style.paint("fill-extrusion-color-transition", fillExtrusionColorTransition)
    style.paint("fill-extrusion-translate", fillExtrusionTranslate)
    style.paint("fill-extrusion-translate-transition", fillExtrusionTranslateTransition)
    style.paint("fill-extrusion-translate-anchor", fillExtrusionTranslateAnchor)
    style.paint("fill-extrusion-pattern", fillExtrusionPattern)
    style.paint("fill-extrusion-pattern-transition", fillExtrusionPatternTransition)
    style.paint("fill-extrusion-height", fillExtrusionHeight)
    style.paint("fill-extrusion-height-transition", fillExtrusionHeightTransition)
    style.paint("fill-extrusion-base", fillExtrusionBase)
    style.paint("fill-extrusion-base-transition", fillExtrusionBaseTransition)
    style.paint("fill-extrusion-vertical-gradient", fillExtrusionVerticalGradient)
    try style.encode(to: encoder)
  }
}

