/// Client-side hillshading visualization based on DEM data. The implementation supports Mapbox
/// Terrain RGB, Mapzen Terrarium tiles and custom encodings. MapLibre layer type `hillshade`.
public struct TileflowHillshadeLayer: TileflowLayer, Equatable {
  public static let type = "hillshade"
  public var id: String
  /// The application source the layer draws.
  public var source: String
  /// The zoom level from which the layer shows.
  public var minZoom: Double?
  /// The zoom level from which the layer hides.
  public var maxZoom: Double?
  /// Where the layer lies among the map’s own layers; nil lies above them all.
  public var slot: TileflowLayerSlot?
  /// Whether this layer is displayed. Default: `"visible"`.
  public var visibility: TileflowValue<TileflowVisibility>?
  /// The direction of the light source(s) used to generate the hillshading with 0 as the top of the
  /// viewport if `hillshade-illumination-anchor` is set to `viewport` and due north if
  /// `hillshade-illumination-anchor` is set to `map`. Only when `hillshade-method` is set to
  /// `multidirectional` can you specify multiple light sources. From 0 to 359. Default: `335`.
  public var hillshadeIlluminationDirection: TileflowValue<[Double]>?
  /// The altitude of the light source(s) used to generate the hillshading with 0 as sunset and 90
  /// as noon. Only when `hillshade-method` is set to `multidirectional` can you specify multiple
  /// light sources. From 0 to 90. Default: `45`.
  public var hillshadeIlluminationAltitude: TileflowValue<[Double]>?
  /// Direction of light source when map is rotated. Default: `"viewport"`.
  public var hillshadeIlluminationAnchor: TileflowValue<TileflowHillshadeIlluminationAnchor>?
  /// Intensity of the hillshade From 0 to 1. Default: `0.5`.
  public var hillshadeExaggeration: TileflowValue<Double>?
  /// How `hillshadeExaggeration` changes when it is set.
  public var hillshadeExaggerationTransition: TileflowTransition?
  /// The shading color of areas that face away from the light source(s). Only when
  /// `hillshade-method` is set to `multidirectional` can you specify multiple light sources.
  /// Default: `"#000000"`.
  public var hillshadeShadowColor: TileflowValue<[TileflowColor]>?
  /// How `hillshadeShadowColor` changes when it is set.
  public var hillshadeShadowColorTransition: TileflowTransition?
  /// The shading color of areas that faces towards the light source(s). Only when
  /// `hillshade-method` is set to `multidirectional` can you specify multiple light sources.
  /// Default: `"#FFFFFF"`.
  public var hillshadeHighlightColor: TileflowValue<[TileflowColor]>?
  /// How `hillshadeHighlightColor` changes when it is set.
  public var hillshadeHighlightColorTransition: TileflowTransition?
  /// The shading color used to accentuate rugged terrain like sharp cliffs and gorges. Default:
  /// `"#000000"`.
  public var hillshadeAccentColor: TileflowValue<TileflowColor>?
  /// How `hillshadeAccentColor` changes when it is set.
  public var hillshadeAccentColorTransition: TileflowTransition?
  /// The hillshade algorithm to use, one of `standard`, `basic`, `combined`, `igor`, or
  /// `multidirectional`. !Visual comparison of standard, basic, igor, combined, and
  /// multidirectional hillshade-method Default: `"standard"`.
  public var hillshadeMethod: TileflowValue<TileflowHillshadeMethod>?
  /// The resampling/interpolation method to use for overscaling, also known as texture
  /// magnification filter. !Visual comparison of linear resampling versus nearest resampling
  /// Default: `"linear"`.
  public var resampling: TileflowValue<TileflowResampling>?

  public init(id: String, source: String) {
    self.id = id
    self.source = source
  }

  public func encode(to encoder: any Encoder) throws {
    var style = StyleLayerEncoding(id: id, type: Self.type)
    style.source = source
    style.minZoom = minZoom
    style.maxZoom = maxZoom
    style.layout("visibility", visibility)
    style.paint("hillshade-illumination-direction", hillshadeIlluminationDirection)
    style.paint("hillshade-illumination-altitude", hillshadeIlluminationAltitude)
    style.paint("hillshade-illumination-anchor", hillshadeIlluminationAnchor)
    style.paint("hillshade-exaggeration", hillshadeExaggeration)
    style.paint("hillshade-exaggeration-transition", hillshadeExaggerationTransition)
    style.paint("hillshade-shadow-color", hillshadeShadowColor)
    style.paint("hillshade-shadow-color-transition", hillshadeShadowColorTransition)
    style.paint("hillshade-highlight-color", hillshadeHighlightColor)
    style.paint("hillshade-highlight-color-transition", hillshadeHighlightColorTransition)
    style.paint("hillshade-accent-color", hillshadeAccentColor)
    style.paint("hillshade-accent-color-transition", hillshadeAccentColorTransition)
    style.paint("hillshade-method", hillshadeMethod)
    style.paint("resampling", resampling)
    try style.encode(to: encoder)
  }
}

